node -e "
const { roundRatio } = require('./src/rounding');
const { buildInvoice } = require('./src');

// half-even: 0.5->0, 1.5->2, 2.5->2, -0.5->0, -1.5->-2, -2.5->-2
console.log('halves:', [1,3,5,-1,-3,-5].map(n => roundRatio(BigInt(n), 2n)));
// exact beyond Number precision: (2^53+1)/1 stays exact, unsafe rejects
console.log('big exact:', roundRatio(9007199254740993n, 1n));
try { roundRatio(9007199254740993n * 10n, 1n); } catch (e) { console.log('unsafe ->', e.constructor.name); }

// invoice tax mode, mixed rates + credit
const inv = buildInvoice({ currency: 'USD', taxMode: 'invoice', lines: [
  { unitCents: 333, taxBps: 1000 }, { unitCents: 333, taxBps: 1000 }, { unitCents: -200, taxBps: 1000 },
]});
console.log('invoice-mode lines tax:', inv.lines.map(l => l.taxCents), 'total', inv.taxCents, inv.totalCents);

// invoice discount allocated once across positive balances, credit untouched
const d = buildInvoice({ currency: 'USD', discounts: [{ type: 'percent', rateBps: 1000 }], lines: [
  { unitCents: 100 }, { unitCents: 205 }, { unitCents: -50 },
]});
console.log('inv discount nets:', d.lines.map(l => l.netCents), 'disc', d.discountCents, 'net', d.netCents);

// ordered discounts on a credit: percent shrinks credit, fixed does not
const c = buildInvoice({ currency: 'USD', lines: [{ unitCents: -105, discounts: [{ type: 'percent', rateBps: 5000 }, { type: 'fixed', amountCents: 10 }] }]});
console.log('credit net:', c.lines[0].netCents);

// fixed-then-percent order now honored
const o = buildInvoice({ currency: 'USD', lines: [{ unitCents: 105, discounts: [{ type: 'fixed', amountCents: 10 }, { type: 'percent', rateBps: 5000 }] }]});
console.log('fixed-first net:', o.lines[0].netCents); // (105-10)=95, 50% off 95: round(47.5)=48 -> 47
"

