1:'use strict';
2:const { parseInvoice } = require('./parse');
3:const { product, sum, difference } = require('./money');
4:const { applyDiscounts } = require('./discounts');
5:const { allocateDiscount } = require('./allocation');
6:const { calculateTaxes } = require('./tax');
7:
8:/**
9: * buildInvoice(input) -> a new invoice breakdown. See parse.js for the input
10: * schema, discounts.js for sequential discounts, rounding.js for exact half-even
11: * cents, allocation.js for remainder/tie rules, and tax.js for both tax modes.
12: *
13: * Pipeline: multiply unitCents by quantity; apply each line's discount list;
14: * compute the invoice discount against the SUM OF POSITIVE remaining balances
15: * (only when invoice discounts are present); apply the invoice discount list
16: * to that basis; allocate the resulting aggregate reduction ONCE across those
17: * positive balances; compute tax. Credits are excluded from invoice discounts
18: * but still contribute to all signed totals and their tax-rate group.
19: *
20: * Output lines preserve input order and contain currency, unitCents, quantity,
21: * grossCents, discountCents, netCents, taxBps, taxCents, totalCents. The returned
22: * invoice contains currency, taxMode, lines, subtotalCents (sum of gross),
23: * discountCents (sum of signed gross - net, including both discount levels),
